// 0.5 Preflight
// The ONE place where configuration is defined, typed and validated, and where every check that must
// pass before the run may change anything is made: config, pause switch, lock, today's spend, and
// whether the AI dependency actually answers (0.4 made one tiny real call).
// Every other node reads its settings from here:  const { config: C } = $('0.5 Preflight').first().json;

const REQUIRED = ['llm_model', 'run_lock'];   // no safe default exists for these
const DEFAULTS = {
  pipeline_enabled: true,
  // Daily budgets (YouTube quota day = Pacific day)
  daily_yt_units_limit: 9000,
  daily_tavily_credit_limit: 100,
  daily_llm_usd_limit: 1,
  // Per-run caps (bound the blast radius of any single run)
  max_search_calls_per_run: 10,
  max_new_candidates_per_run: 60,
  max_enrich_per_run: 60,
  max_research_per_run: 15,
  max_notes_per_run: 15,
  max_rechecks_per_run: 20,
  // Discovery
  discovery_window_days: 30,
  search_order: 'relevance',
  search_region: 'US',
  search_language: 'en',
  // Qualification gates (1, 2, 4a) and metric definitions
  min_subs: 1000,
  min_channel_age_days: 90,
  max_dormant_days: 45,
  allowed_countries: 'US,GB,CA,AU,NZ,IE',
  allowed_languages: 'en',
  shorts_max_seconds: 180,
  longform_min_minutes: 10,
  uploads_lookback_days: 90,
  uploads_max_pages: 6,
  // Scoring
  tier_a_min: 75,
  tier_b_min: 55,
  // Rechecks (nurture / needs-info leads come back automatically)
  nurture_recheck_days: 90,
  needs_info_recheck_days: 30,
  max_rechecks: 2,
  // AI (Gemini REST, enforced JSON) and research
  llm_model: '',
  llm_usd_per_m_input: 0.75,
  llm_usd_per_m_output: 3.75,
  llm_est_usd_per_call: 0.01,
  tavily_credits_per_lead: 2,
  // Operations
  lock_stale_minutes: 180,
  heartbeat_url: '',
};

// ---------- 1. Settings -> typed config ----------
const raw = {};
for (const { json: r } of $('0.2 Read Settings').all()) {
  const k = String(r.key ?? '').trim();
  if (k) raw[k] = r.value;
}
const config = {};
const config_errors = [];
const warnings = [];
for (const [k, def] of Object.entries(DEFAULTS)) {
  const v = raw[k];
  if (v === undefined || v === null || String(v).trim() === '') { config[k] = def; continue; }
  if (typeof def === 'number') {
    const n = Number(String(v).replace(/,/g, '').trim());
    if (Number.isFinite(n) && n >= 0) config[k] = n;
    else { config[k] = def; config_errors.push(`${k} must be a non-negative number (got "${v}")`); }
  } else if (typeof def === 'boolean') {
    config[k] = /^(true|yes|1|on)$/i.test(String(v).trim());
  } else {
    config[k] = String(v).trim();
  }
}
for (const k of REQUIRED) if (!String(raw[k] ?? '').trim()) config_errors.push(`Settings row "${k}" is missing or empty`);
config.llm_model = config.llm_model.replace(/^models\//, '');
config.allowed_countries_list = config.allowed_countries.split(',').map(s => s.trim().toUpperCase()).filter(Boolean);
config.allowed_languages_list = config.allowed_languages.split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
if (config.tier_a_min <= config.tier_b_min) config_errors.push('tier_a_min must be greater than tier_b_min');
if (!['relevance', 'date', 'viewCount', 'rating'].includes(config.search_order)) config_errors.push('search_order must be relevance, date, viewCount or rating');
if (!config.heartbeat_url) warnings.push('HEARTBEAT_DISABLED (set heartbeat_url in Settings)');

// ---------- 2. Lock ("run_id|acquired_at|execution_id" or FREE) ----------
const now = DateTime.now();
const lockRaw = String(raw.run_lock ?? '').trim();
let lock = { held: false, value: lockRaw || 'FREE' };
if (lockRaw && lockRaw.toUpperCase() !== 'FREE') {
  const [runId, at, execId] = lockRaw.split('|');
  const acquired = DateTime.fromISO(String(at || ''));
  const ageMin = acquired.isValid ? Math.round(now.diff(acquired, 'minutes').minutes) : null;
  const stale = ageMin === null || ageMin >= config.lock_stale_minutes;
  lock = { held: !stale, stale, value: lockRaw, run_id: runId, execution_id: execId, age_minutes: ageMin };
}

// ---------- 3. Today's spend (Pacific day, the YouTube quota day) ----------
const toISODate = v => {
  if (v === null || v === undefined || v === '') return '';
  if (typeof v === 'number') return DateTime.fromMillis(Date.UTC(1899, 11, 30) + v * 86400000, { zone: 'utc' }).toISODate();
  const iso = DateTime.fromISO(String(v).trim());
  if (iso.isValid) return iso.toISODate();
  const t = Date.parse(String(v));
  return Number.isFinite(t) ? DateTime.fromMillis(t).toISODate() : '';
};
const num = v => { const n = Number(String(v ?? '').replace(/[^0-9.\-]/g, '')); return Number.isFinite(n) ? n : 0; };
const pt = now.setZone('America/Los_Angeles');
const today = pt.toISODate();
const spent = { yt_units: 0, tavily_credits: 0, llm_usd: 0 };
for (const { json: r } of $('0.3 Read Run Log').all()) {
  if (!r.run_id || toISODate(r.run_date_pt) !== today) continue;
  spent.yt_units += num(r.yt_units_est);
  spent.tavily_credits += num(r.tavily_credits);
  spent.llm_usd += num(r.llm_cost_est_usd);
}
const limit = { yt_units: config.daily_yt_units_limit, tavily_credits: config.daily_tavily_credit_limit, llm_usd: config.daily_llm_usd_limit };
const remaining = {
  yt_units: Math.max(0, limit.yt_units - spent.yt_units),
  tavily_credits: Math.max(0, limit.tavily_credits - spent.tavily_credits),
  llm_usd: Math.max(0, +(limit.llm_usd - spent.llm_usd).toFixed(4)),
};

// ---------- 4. Dependency check: did the AI model answer one real request? ----------
const ping = $('0.4 Check AI').first().json;
const scrub = s => String(s || '').replace(/AIza[0-9A-Za-z_-]{20,}/g, '[KEY]').replace(/\s+/g, ' ').trim();
const aiError = ping.error ? scrub(ping.error.description || ping.error.message).slice(0, 220) : '';
const deps = { ai_ok: !aiError && !!config.llm_model, ai_error: aiError };
if (!deps.ai_ok) warnings.push(`AI_UNAVAILABLE: ${aiError || 'llm_model not set'}`);

// ---------- 5. Run identity ----------
let trigger_type = 'MANUAL';
try { if ($('0.1a Daily Schedule').isExecuted) trigger_type = 'SCHEDULE'; } catch (e) { /* manual run */ }
const run = {
  run_id: `R-${pt.toFormat('yyyyMMdd-HHmmss')}`,
  run_date_pt: today,
  started_at: now.toUTC().toISO(),
  execution_id: String($execution.id),
  trigger_type,
};

// ---------- 6. Verdict ----------
// A missing AI does not stop the run: YouTube phases still run, research and notes wait (DEGRADED).
let skip_reason = '';
let skip_detail = '';
if (config_errors.length) { skip_reason = 'CONFIG_INVALID'; skip_detail = config_errors.join('; '); }
else if (!config.pipeline_enabled) { skip_reason = 'PAUSED'; skip_detail = 'pipeline_enabled = false'; }
else if (lock.held) { skip_reason = 'LOCKED'; skip_detail = `held by ${lock.run_id} for ${lock.age_minutes} min`; }

return [{ json: { can_run: !skip_reason, skip_reason, skip_detail, run, config, deps, budget: { spent, limit, remaining }, lock, config_errors, warnings } }];

// 1.2 Plan Rechecks
// Waiting leads (CLOSED_NURTURE / NEEDS_INFO) whose recheck date has arrived go back to DISCOVERED,
// so they are re-screened with fresh numbers. Each lead gets at most `max_rechecks` second chances.
const { config: C, run } = $('0.5 Preflight').first().json;

const toISODate = v => {
  if (v === null || v === undefined || v === '') return '';
  if (typeof v === 'number') return DateTime.fromMillis(Date.UTC(1899, 11, 30) + v * 86400000, { zone: 'utc' }).toISODate();
  const iso = DateTime.fromISO(String(v).trim());
  if (iso.isValid) return iso.toISODate();
  const t = Date.parse(String(v));
  return Number.isFinite(t) ? DateTime.fromMillis(t).toISODate() : '';
};
const WAITING = ['CLOSED_NURTURE', 'NEEDS_INFO'];

const due = $input.all()
  .map(i => i.json)
  .filter(l => l.channel_id && WAITING.includes(String(l.pipeline_stage || '').trim()))
  .map(l => ({ lead: l, due: toISODate(l.recheck_after), tries: Number(l.retry_count) || 0 }))
  .filter(x => x.due && x.due <= run.run_date_pt && x.tries < C.max_rechecks)
  .sort((a, b) => a.due.localeCompare(b.due))
  .slice(0, C.max_rechecks_per_run);

if (!due.length) return [{ json: { work: false } }];

return due.map(({ lead, tries }) => ({ json: {
  work: true,
  channel_id: lead.channel_id,
  pipeline_stage: 'DISCOVERED',
  retry_count: tries + 1,
  recheck_after: '',
  last_error_code: '',
  reason_code: 'RECHECK',
  reason_text: `Recheck ${tries + 1}/${C.max_rechecks} (was ${lead.pipeline_stage}: ${lead.reason_code || 'n/a'})`,
  last_updated_at: run.started_at,
  last_run_id: run.run_id,
} }));

// 1.6 Plan Discovery
// Turns ACTIVE Inputs rows into YouTube request specs that one HTTP node executes:
//   SEARCH_TERM -> search.list (100 units)   SEED -> channels.list (1 unit)
// Search terms rotate (least recently run first) and are capped by the YouTube units left today
// after reserving enough for screening and measuring.
const { config: C, budget } = $('0.5 Preflight').first().json;
const UNITS_PER_CHANNEL = 4;   // conservative: measured ~3 per measured channel, ~0.02 per screened-out one
const API = 'https://www.googleapis.com/youtube/v3';

const rows = $input.all().map(i => i.json).filter(r => String(r.input_id || '').trim());
const kind = r => String(r.row_type || '').trim().toUpperCase();

function parseSeed(value) {
  const s = String(value || '').trim();
  let m;
  if ((m = s.match(/(UC[A-Za-z0-9_-]{22})/))) return { id: m[1] };
  if ((m = s.match(/youtube\.com\/@([^\/?#\s]+)/i)) || (m = s.match(/^@([^\/?#\s]+)$/))) return { forHandle: '@' + m[1] };
  if ((m = s.match(/youtube\.com\/user\/([^\/?#\s]+)/i))) return { forUsername: m[1] };
  if (/^https?:|youtube\.com\//i.test(s)) return null;           // /c/ custom URLs can't be resolved for 1 unit
  if (/^[A-Za-z0-9._-]{3,}$/.test(s)) return { forHandle: '@' + s };
  return null;
}

const seeds = rows.filter(r => kind(r) === 'SEED')
  .map(r => ({ r, q: parseSeed(r.value) }))
  .filter(x => x.q)
  .slice(0, Math.max(0, budget.remaining.yt_units));             // 1 unit each

const reserve = C.max_enrich_per_run * UNITS_PER_CHANNEL;
const affordable = Math.max(0, Math.floor((budget.remaining.yt_units - reserve - seeds.length) / 100));
const termsAll = rows.filter(r => kind(r) === 'SEARCH_TERM' && String(r.value || '').trim())
  .sort((a, b) => String(a.last_run_at || '').localeCompare(String(b.last_run_at || '')));
const terms = termsAll.slice(0, Math.min(C.max_search_calls_per_run, affordable));

const publishedAfter = DateTime.now().minus({ days: C.discovery_window_days }).toUTC().startOf('second')
  .toISO({ suppressMilliseconds: true });

const out = [
  ...seeds.map(({ r, q }) => ({
    work: true, kind: 'SEED', input_id: r.input_id, label: String(r.value).trim(),
    url: `${API}/channels`,
    qs: { part: 'id,snippet', fields: 'items(id,snippet/title)', ...q },
  })),
  ...terms.map(r => ({
    work: true, kind: 'SEARCH', input_id: r.input_id, label: String(r.value).trim(),
    url: `${API}/search`,
    qs: {
      part: 'snippet', type: 'video', videoDuration: 'long', maxResults: 50, order: C.search_order,
      regionCode: C.search_region, relevanceLanguage: C.search_language,
      q: String(r.value).trim(), publishedAfter,
      fields: 'items(snippet(channelId,channelTitle))',
    },
  })),
];

const meta = {
  seeds: seeds.length,
  terms_available: termsAll.length,
  terms_selected: terms.length,
  limited_by_budget: terms.length < Math.min(C.max_search_calls_per_run, termsAll.length),
};
if (!out.length) return [{ json: { work: false, _meta: meta } }];
out[0]._meta = meta;
return out.map(json => ({ json }));

// 1.9 Collect Candidates
// Joins every YouTube response back to the Inputs row that produced it, drops channels we already know,
// applies the per-run cap and decides how each Inputs row is updated.
// Output: one item per Inputs row to update; the new leads ride along in `new_leads`.
const { config: C, run } = $('0.5 Preflight').first().json;

// ---- Failure triage: a broken dependency stops the run (LE-99 alerts); a bad item does not ----
const failText = e => [e.description, e.message, e.cause && e.cause.message].filter(Boolean).join(' ').replace(/\s+/g, ' ');
const SYSTEMIC = /quotaExceeded|dailyLimitExceeded|rateLimitExceeded|keyInvalid|keyExpired|accessNotConfigured|ipRefererBlocked|API key not valid|API_KEY_INVALID/i;
const results = $input.all().map(i => i.json);
const failed = results.filter(r => r.error);
const hard = failed.find(r => SYSTEMIC.test(failText(r.error)));
if (hard || (results.length >= 2 && failed.length === results.length)) {
  throw new Error(`YOUTUBE_UNAVAILABLE: ${failText((hard || failed[0]).error).slice(0, 240)}`);
}

const ID = /^UC[A-Za-z0-9_-]{22}$/;
const plans = $('1.6 Plan Discovery').all();
const planFor = i => {
  try { const m = $('1.6 Plan Discovery').itemMatching(i); if (m) return m.json; } catch (e) { /* fall back to order */ }
  return plans[i].json;
};
const known = new Set($('1.1 Read Leads').all().map(i => String(i.json.channel_id || '').trim()).filter(Boolean));
const pairs = results.map((res, i) => ({ res, plan: planFor(i) }));
pairs.sort((a, b) => (a.plan.kind === 'SEED' ? 0 : 1) - (b.plan.kind === 'SEED' ? 0 : 1)); // seeds win attribution

const found = new Map();
const perInput = new Map();
for (const { res, plan } of pairs) {
  const st = { plan, error: !!res.error, results: 0 };
  perInput.set(plan.input_id, st);
  if (res.error) continue;
  for (const it of res.items || []) {
    const id = plan.kind === 'SEED' ? it.id : it.snippet?.channelId;
    if (!ID.test(String(id || ''))) continue;
    st.results++;
    if (!found.has(id)) {
      found.set(id, {
        channel_id: id,
        channel_name: (plan.kind === 'SEED' ? it.snippet?.title : it.snippet?.channelTitle) || '',
        source: `${plan.kind}:${plan.input_id}`,
        input_id: plan.input_id,
      });
    }
  }
}

const unknown = [...found.values()].filter(c => !known.has(c.channel_id));
const fresh = unknown.slice(0, C.max_new_candidates_per_run);

// Inputs updates: search terms stay ACTIVE (they rotate); seeds become PROCESSED or FAILED.
// A row whose request failed is left as it was (retried tomorrow).
const updates = [];
for (const [inputId, st] of perInput) {
  if (st.error) continue;
  const mine = fresh.filter(c => c.input_id === inputId);
  const status = st.plan.kind === 'SEED' ? (st.results ? 'PROCESSED' : 'FAILED') : 'ACTIVE';
  updates.push({ input_id: inputId, status, last_run_at: run.started_at, last_yield: mine.length, new_leads: mine });
}
// Seed rows that cannot be resolved at all (e.g. /c/ custom URLs) are marked FAILED
const planned = new Set(plans.map(p => p.json.input_id));
for (const { json: r } of $('1.5 Read Inputs').all()) {
  if (String(r.row_type || '').trim().toUpperCase() === 'SEED' && r.input_id && !planned.has(r.input_id)) {
    updates.push({ input_id: r.input_id, status: 'FAILED', last_run_at: run.started_at, last_yield: 0, new_leads: [] });
  }
}

const stats = {
  requests: pairs.length,
  request_errors: failed.length,
  candidates_found: found.size,
  already_known: found.size - unknown.length,
  trimmed_by_cap: unknown.length - fresh.length,
  selected: fresh.length,
};
if (!updates.length) return [{ json: { work: false, new_leads: [], _stats: stats } }];
updates[0]._stats = stats;
return updates.map(json => ({ json: { work: true, ...json } }));

// 1.12 Select New Leads
// Flattens the new leads attached to the Inputs updates into one item per lead to register.
const leads = $('1.9 Collect Candidates').all().flatMap(i => i.json.new_leads || []);
if (!leads.length) return [{ json: { work: false } }];
return leads.map(l => ({ json: { work: true, ...l } }));

// 2.2 Plan Screening
// Picks DISCOVERED leads (oldest first; legacy ENRICHED rows too), caps them by the per-run limit and by
// the YouTube units left today, and batches 50 ids per channels.list call (1 unit per batch).
const { config: C, budget } = $('0.5 Preflight').first().json;
const UNITS_PER_CHANNEL = 4;   // conservative: measured ~3 per measured channel, ~0.02 per screened-out one

let unitsUsed = 0;   // spent by Phase 1 in this run
try {
  if ($('1.8 Query YouTube').isExecuted) {
    unitsUsed = $('1.6 Plan Discovery').all().reduce((s, i) => s + (i.json.kind === 'SEARCH' ? 100 : i.json.kind === 'SEED' ? 1 : 0), 0);
  }
} catch (e) { /* Phase 1 made no calls */ }
const affordable = Math.max(0, Math.floor((budget.remaining.yt_units - unitsUsed) / UNITS_PER_CHANNEL));

const eligible = $input.all()
  .map(i => i.json)
  .filter(l => l.channel_id && ['DISCOVERED', 'ENRICHED'].includes(String(l.pipeline_stage || '').trim()))
  .sort((a, b) => String(a.first_seen_at || '').localeCompare(String(b.first_seen_at || '')));
const cap = Math.min(C.max_enrich_per_run, affordable);
const selected = eligible.slice(0, cap);
const meta = { eligible: eligible.length, selected: selected.length, limited_by_budget: affordable < Math.min(C.max_enrich_per_run, eligible.length) };

if (!selected.length) return [{ json: { work: false, _meta: meta } }];

const out = [];
for (let i = 0; i < selected.length; i += 50) {
  const batch = selected.slice(i, i + 50);
  out.push({ json: {
    work: true,
    ids: batch.map(l => l.channel_id).join(','),
    leads: batch.map(l => ({ channel_id: l.channel_id, channel_name: l.channel_name || '', retry_count: Number(l.retry_count) || 0 })),
  } });
}
out[0].json._meta = meta;
return out;

// 2.5 Screen Channels
// Cheapest checks first. channels.list (1 unit per 50 channels) already tells us availability,
// size, age, country and language, so Gates 1 and 4a run here and only survivors (work: true) are
// measured with the expensive upload and video lookups.
const { config: C } = $('0.5 Preflight').first().json;
const DAY = 86400000;
const now = Date.now();

// ---- Failure triage: a broken dependency stops the run; a bad item does not ----
const failText = e => [e.description, e.message, e.cause && e.cause.message].filter(Boolean).join(' ').replace(/\s+/g, ' ');
const SYSTEMIC = /quotaExceeded|dailyLimitExceeded|rateLimitExceeded|keyInvalid|keyExpired|accessNotConfigured|ipRefererBlocked|API key not valid|API_KEY_INVALID/i;
const results = $input.all().map(i => i.json);
const failed = results.filter(r => r.error);
const hard = failed.find(r => SYSTEMIC.test(failText(r.error)));
if (hard || (results.length >= 2 && failed.length === results.length)) {
  throw new Error(`YOUTUBE_UNAVAILABLE: ${failText((hard || failed[0]).error).slice(0, 240)}`);
}

const plans = $('2.2 Plan Screening').all();
const planFor = i => {
  try { const m = $('2.2 Plan Screening').itemMatching(i); if (m) return m.json; } catch (e) { /* order fallback */ }
  return plans[i].json;
};
const allowedLang = l => C.allowed_languages_list.some(a => l === a || l.startsWith(`${a}-`));

const out = [];
results.forEach((res, i) => {
  const plan = planFor(i);
  const byId = new Map((res.items || []).map(c => [c.id, c]));
  for (const lead of plan.leads || []) {
    const c = byId.get(lead.channel_id);
    const sn = c?.snippet || {};
    const st = c?.statistics || {};
    const hidden = !!st.hiddenSubscriberCount;
    const subs = hidden ? null : Number(st.subscriberCount ?? 0);
    const created = Date.parse(sn.publishedAt || '');
    const ageDays = Number.isFinite(created) ? Math.floor((now - created) / DAY) : null;
    const country = String(sn.country || '').toUpperCase();
    const lang = String(sn.defaultLanguage || '').toLowerCase();

    // Screening decision (first failing rule wins)
    let screen = null;
    if (res.error) screen = ['NEEDS_INFO', 'Data', 'CHANNEL_FETCH_FAILED', 'YouTube channel lookup failed; retried tomorrow', 1];
    else if (!c) screen = ['REJECTED', 'Data', 'CHANNEL_UNAVAILABLE', 'Channel not returned by YouTube (deleted, terminated or private)'];
    else if (ageDays !== null && ageDays < C.min_channel_age_days) screen = ['NURTURE', 'Gate 1', 'TOO_NEW', `Gate 1: channel is ${ageDays} days old (min ${C.min_channel_age_days})`, C.nurture_recheck_days];
    else if (subs !== null && subs < C.min_subs) screen = ['NURTURE', 'Gate 1', 'TOO_SMALL', `Gate 1: ${subs} subscribers (min ${C.min_subs})`, C.nurture_recheck_days];
    else if (country && !C.allowed_countries_list.includes(country)) screen = ['REJECTED', 'Gate 4a', 'GEO_BLOCKED', `Gate 4a: channel country ${country} not in ${C.allowed_countries_list.join('/')}`];
    else if (lang && !allowedLang(lang)) screen = ['REJECTED', 'Gate 4a', 'LANGUAGE_BLOCKED', `Gate 4a: channel language ${lang} not in ${C.allowed_languages_list.join('/')}`];

    out.push({ json: {
      work: !screen,                                   // survivors go on to be measured
      screen: screen ? { outcome: screen[0], rule: screen[1], code: screen[2], text: screen[3], recheck_days: screen[4] || 0 } : null,
      channel_id: lead.channel_id,
      retry_count: lead.retry_count,
      channel_name: sn.title || lead.channel_name || '',
      channel_url: `https://www.youtube.com/channel/${lead.channel_id}`,
      handle: sn.customUrl || '',
      country,
      default_language: lang,
      channel_created_at: sn.publishedAt || '',
      description_excerpt: String(sn.description || '').replace(/\s+/g, ' ').trim().slice(0, 1000),
      subscriber_count: hidden ? '' : subs,
      subscribers_hidden: hidden ? 'TRUE' : 'FALSE',
      view_count: Number(st.viewCount ?? 0),
      video_count: Number(st.videoCount ?? 0),
      uploads_playlist_id: c?.contentDetails?.relatedPlaylists?.uploads || `UU${lead.channel_id.slice(2)}`,
    } });
  }
});
return out;

// 2.9 Plan Video Lookups
// Groups the paginated upload lists by channel, keeps only videos inside the lookback window and packs
// their ids 50 per videos.list call (calls are shared across channels to save quota).
const { config: C } = $('0.5 Preflight').first().json;

// ---- Failure triage: quota / key problems stop the run; a private or missing playlist does not ----
const failText = e => [e.description, e.message, e.cause && e.cause.message].filter(Boolean).join(' ').replace(/\s+/g, ' ');
const SYSTEMIC = /quotaExceeded|dailyLimitExceeded|rateLimitExceeded|keyInvalid|keyExpired|accessNotConfigured|ipRefererBlocked|API key not valid|API_KEY_INVALID/i;
const pages = $input.all().map(i => i.json);
const failed = pages.filter(p => p.error);
const hard = failed.find(p => SYSTEMIC.test(failText(p.error)));
if (hard || (pages.length >= 3 && failed.length === pages.length)) {
  throw new Error(`YOUTUBE_UNAVAILABLE: ${failText((hard || failed[0]).error).slice(0, 240)}`);
}

const cutoff = DateTime.now().minus({ days: C.uploads_lookback_days }).toMillis();
const channels = $('2.7 Keep Survivors').all().map(i => i.json);
const uploads = Object.fromEntries(channels.map(c => [c.channel_id, { pages: 0, error: false, next: false, newestOnLast: null, ids: [] }]));

pages.forEach((page, i) => {
  const pl = page.items?.[0]?.snippet?.playlistId;
  let cid = pl && pl.startsWith('UU') ? `UC${pl.slice(2)}` : null;
  if (!cid) { try { cid = $('2.7 Keep Survivors').itemMatching(i)?.json.channel_id; } catch (e) { /* unattributed */ } }
  const u = uploads[cid];
  if (!u) return;
  u.pages++;
  if (page.error) { u.error = true; return; }
  u.next = !!page.nextPageToken;                      // pages arrive in order: the last one wins
  let newest = null;
  for (const it of page.items || []) {
    const vid = it.contentDetails?.videoId;
    const t = Date.parse(it.contentDetails?.videoPublishedAt || '');
    if (!vid || !Number.isFinite(t)) continue;
    newest = newest === null ? t : Math.max(newest, t);
    if (t >= cutoff) u.ids.push(vid);
  }
  u.newestOnLast = newest;
});

const summary = {};
const pool = [];
for (const [cid, u] of Object.entries(uploads)) {
  const ids = [...new Set(u.ids)];
  // truncated = we stopped at the page limit while the last page was still inside the lookback window
  summary[cid] = { pages: u.pages, error: u.error, truncated: u.next && u.newestOnLast !== null && u.newestOnLast >= cutoff, listed: ids.length };
  for (const id of ids) pool.push({ id, cid });
}

const chunks = [];
for (let i = 0; i < pool.length; i += 50) {
  const part = pool.slice(i, i + 50);
  chunks.push({ ids: part.map(p => p.id).join(','), channels: [...new Set(part.map(p => p.cid))] });
}
// No recent uploads anywhere: one harmless lookup ("NONE" returns an empty list) keeps the flow linear
if (!chunks.length) chunks.push({ ids: 'NONE', channels: [] });
chunks[0]._uploads = summary;
return chunks.map(json => ({ json }));

// 2.11 Decide Qualification
// Pure decision function for Phase 2, and the only place its stage contract lives.
//  - screened-out leads (2.5) keep their screening decision
//  - survivors get publishing metrics from recent uploads, then Gate 2 (dormant), the Shorts gap class
//    and the 45-point pre-score (= gap + consistency parts of the final rubric, so ranking and scoring agree)
// A Short is a vertical (or square) video of at most `shorts_max_seconds`, using the player aspect ratio
// YouTube reports; if the ratio is unknown it falls back to duration <= 60 s.
const { config: C, run } = $('0.5 Preflight').first().json;
const DAY = 86400000;
const now = Date.now();
const since60 = now - 60 * DAY;
const since90 = now - 90 * DAY;
const SHORT_MAX = C.shorts_max_seconds;
const LONG_MIN = C.longform_min_minutes * 60;
const plusDays = d => DateTime.fromMillis(now).setZone('America/Los_Angeles').plus({ days: d }).toISODate();
const ran = n => { try { return $(n).isExecuted; } catch (e) { return false; } };

// Rubric parts shared with 3.8 Score Lead (persisted as score_gap / score_consistency)
const gapScore = g => ({ STRONG: 30, MODERATE: 18 }[g] ?? 5);
const consistencyScore = (long60, maxGap) =>
  long60 >= 8 && maxGap <= 14 ? 15 : long60 >= 4 && maxGap <= 21 ? 12 : long60 >= 2 ? 8 : 5;

// Stage contract for Phase 2
function settle(outcome, retries, recheckDays) {
  if (outcome === 'CONTINUE') return { pipeline_stage: 'QUALIFIED', recheck_after: '' };
  if (outcome === 'REJECTED') return { pipeline_stage: 'CLOSED_REJECTED', recheck_after: '' };
  const canRecheck = retries < C.max_rechecks;
  return { pipeline_stage: outcome === 'NURTURE' ? 'CLOSED_NURTURE' : 'NEEDS_INFO', recheck_after: canRecheck ? plusDays(recheckDays) : '' };
}

// ---------- measurement inputs (only when survivors were measured) ----------
const measured = ran('2.10 Fetch Videos');
const videosBy = {};
const videoErrors = new Set();
let uploads = {};
if (measured) {
  const failText = e => [e.description, e.message, e.cause && e.cause.message].filter(Boolean).join(' ').replace(/\s+/g, ' ');
  const SYSTEMIC = /quotaExceeded|dailyLimitExceeded|rateLimitExceeded|keyInvalid|keyExpired|accessNotConfigured|ipRefererBlocked|API key not valid|API_KEY_INVALID/i;
  const results = $input.all().map(i => i.json);
  const failed = results.filter(r => r.error);
  const hard = failed.find(r => SYSTEMIC.test(failText(r.error)));
  if (hard || (results.length >= 2 && failed.length === results.length)) {
    throw new Error(`YOUTUBE_UNAVAILABLE: ${failText((hard || failed[0]).error).slice(0, 240)}`);
  }
  const chunks = $('2.9 Plan Video Lookups').all();
  uploads = chunks[0].json._uploads || {};
  const toSeconds = iso => {
    const m = String(iso || '').match(/^P(?:(\d+)D)?(?:T(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?)?$/);
    return m ? (+m[1] || 0) * 86400 + (+m[2] || 0) * 3600 + (+m[3] || 0) * 60 + (+m[4] || 0) : 0;
  };
  results.forEach((res, i) => {
    if (res.error) {
      let chunk = null;
      try { chunk = $('2.9 Plan Video Lookups').itemMatching(i)?.json; } catch (e) { chunk = chunks[i]?.json; }
      for (const cid of chunk?.channels || []) videoErrors.add(cid);
      return;
    }
    for (const v of res.items || []) {
      const sn = v.snippet, cd = v.contentDetails;
      if (!sn || !cd || sn.liveBroadcastContent === 'live' || sn.liveBroadcastContent === 'upcoming') continue;
      const sec = toSeconds(cd.duration);
      const t = Date.parse(sn.publishedAt);
      if (!sec || !Number.isFinite(t)) continue;
      const w = Number(v.player?.embedWidth), h = Number(v.player?.embedHeight);
      const aspectKnown = w > 0 && h > 0;
      (videosBy[sn.channelId] ||= []).push({
        id: v.id, t, sec, hd: cd.definition === 'hd', live: !!v.liveStreamingDetails, aspectKnown, vertical: aspectKnown && h >= w,
      });
    }
  });
}

const days = ms => Math.floor(ms / DAY);
const median = a => { if (!a.length) return 0; const s = [...a].sort((x, y) => x - y); const m = s.length >> 1; return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2; };
const share = (a, f) => (a.length ? +(a.filter(f).length / a.length).toFixed(2) : '');
const watch = v => (v ? `https://www.youtube.com/watch?v=${v.id}` : '');
const isShort = v => v.sec <= SHORT_MAX && (v.aspectKnown ? v.vertical : v.sec <= 60);
const isLong = v => v.sec >= LONG_MIN;

return $('2.5 Screen Channels').all().map(({ json: ch }) => {
  const base = { ...ch, data_checked_at: run.started_at, last_updated_at: run.started_at, last_run_id: run.run_id, last_error_code: '' };
  delete base.work; delete base.screen;
  let outcome, rule, code, text, recheckDays = 0, metrics = {};

  if (ch.screen) {
    ({ outcome, rule, code, text } = ch.screen);
    recheckDays = ch.screen.recheck_days;
    metrics = { yt_units_est: 0.02 };
  } else {
    const u = uploads[ch.channel_id] || { pages: 0, error: false, truncated: false, listed: 0 };
    const missing = [];
    if (u.error) missing.push('UPLOADS_FETCH_FAILED');
    if (videoErrors.has(ch.channel_id)) missing.push('VIDEOS_FETCH_FAILED');
    const vids = (videosBy[ch.channel_id] || []).sort((a, b) => b.t - a.t);
    const in60 = v => v.t >= since60;
    const long = vids.filter(isLong);
    const short = vids.filter(isShort);
    const long60 = long.filter(in60);
    const short60 = short.filter(in60);
    const clips60 = vids.filter(v => in60(v) && !isShort(v) && !isLong(v));   // horizontal clips & mid-length videos
    const shortWindow = vids.filter(v => v.sec <= SHORT_MAX);
    const aspectShare = shortWindow.length ? shortWindow.filter(v => v.aspectKnown).length / shortWindow.length : 1;
    const maxGap = list => {
      if (!list.length) return 60;
      const pts = [now, ...list.map(v => v.t)];
      if (!u.truncated) pts.push(since60);
      let g = 0;
      for (let i = 0; i < pts.length - 1; i++) g = Math.max(g, pts[i] - pts[i + 1]);
      return days(g);
    };
    const sinceLong = long[0] ? days(now - long[0].t) : null;
    metrics = {
      longform_total_seen: long.length,
      longform_60d: long60.length,
      longform_90d: long.filter(v => v.t >= since90).length,
      last_longform_date: long[0] ? new Date(long[0].t).toISOString().slice(0, 10) : '',
      days_since_last_longform: sinceLong ?? '',
      median_longform_minutes: Math.round(median(long60.map(v => v.sec)) / 60),
      max_gap_longform_60d: maxGap(long60),
      shortcand_60d: short60.length,
      shortcand_core_60d: short60.filter(v => v.sec <= 60).length,
      shortcand_total_seen: short.length,
      days_since_last_shortcand: short[0] ? days(now - short[0].t) : '',
      max_gap_shortcand_60d: maxGap(short60),
      midform_60d: clips60.length,
      live_share: share(long60, v => v.live),
      hd_share: share(long60, v => v.hd),
      uploads_fully_listed: u.truncated || u.error ? 'FALSE' : 'TRUE',
      window_truncated: u.truncated ? 'TRUE' : 'FALSE',
      missing_fields: missing.join(', '),
      rep_video_1: watch(long60[0]),
      rep_video_2: watch(long60[1]),
      rep_video_3: watch(long60[2]),
      shorts_tab_url: `https://www.youtube.com/channel/${ch.channel_id}/shorts`,
      gap_method: !shortWindow.length ? 'NO_SHORT_FORM' : aspectShare >= 0.8 ? 'ASPECT_RATIO' : 'DURATION_HEURISTIC',
      gap_confidence: u.truncated || missing.length ? 'LOW' : aspectShare < 0.8 || long60.length < 4 ? 'MEDIUM' : 'HIGH',
      shorts_review_flag: u.truncated || (short60.length === 0 && clips60.length > 0) ? 'TRUE' : 'FALSE',
      yt_units_est: u.pages + Math.ceil(u.listed / 50),
    };

    if (missing.length) {
      [outcome, rule, code, text, recheckDays] = ['NEEDS_INFO', 'Data', 'ENRICHMENT_INCOMPLETE', `YouTube data incomplete: ${missing.join(', ')}; retried tomorrow`, 1];
    } else if (long60.length === 0 && u.truncated) {
      [outcome, rule, code, text, recheckDays] = ['NURTURE', 'Gate 2', 'NO_LONGFORM_IN_WINDOW', 'Gate 2: upload list truncated before any long-form episode was found', C.nurture_recheck_days];
    } else if (long60.length === 0 || sinceLong === null || sinceLong > C.max_dormant_days) {
      [outcome, rule, code, text, recheckDays] = ['NURTURE', 'Gate 2', 'DORMANT',
        `Gate 2: ${long60.length} long-form episodes in 60 days; last one ${sinceLong === null ? `older than ${C.uploads_lookback_days} days` : `${sinceLong} days ago`} (max ${C.max_dormant_days})`,
        C.nurture_recheck_days];
    } else {
      outcome = 'CONTINUE';
      const ratio = +(short60.length / long60.length).toFixed(2);
      const gap_class = short60.length === 0 ? 'STRONG' : ratio < 1 ? 'MODERATE' : 'WEAK';
      const score_gap = gapScore(gap_class);
      const score_consistency = consistencyScore(long60.length, metrics.max_gap_longform_60d);
      Object.assign(metrics, { gap_class, shorts_ratio_60d: ratio, score_gap, score_consistency, pre_score: score_gap + score_consistency });
      code = 'QUALIFIED';
      text = `Gates 1, 2, 4a passed. ${gap_class} gap (${short60.length} Shorts / ${long60.length} episodes in 60 days), pre-score ${score_gap + score_consistency}/45`;
    }
  }

  const state = settle(outcome, Number(ch.retry_count) || 0, recheckDays);
  return { json: {
    ...base,
    gap_class: '', shorts_ratio_60d: '', score_gap: '', score_consistency: '', pre_score: '',
    ...metrics,
    gate_results: outcome === 'CONTINUE' ? 'GATE_1_PASS, GATE_2_PASS, GATE_4A_PASS' : `${rule.toUpperCase().replace(/\s+/g, '_')}_${outcome}`,
    reason_code: code,
    reason_text: text,
    ...state,
    // audit log: rejections only (nurture leads stay in Leads with a recheck date)
    _log: outcome === 'REJECTED' ? {
      rule, reason_code: code, reason_text: text, confidence: 'HIGH', rejected_by: 'RULES_PHASE_2',
      evidence_text: `subs=${ch.subscriber_count === '' ? 'hidden' : ch.subscriber_count}, country=${ch.country || '-'}, lang=${ch.default_language || '-'}`,
    } : null,
    _decision: { outcome, rule },
  } };
});

// 3.2 Plan Research
// Ranks QUALIFIED leads by pre-score (leads that failed research once go last), sizes the batch to what
// today's Tavily and Gemini budgets allow, and emits 2 web searches per lead:
//   1. who runs the show       "<name>" podcast host
//   2. the business itself     scoped to the website found in the channel description, when there is one
// Research waits (no spend) when 0.4 found the AI model unavailable.
const { config: C, budget, deps } = $('0.5 Preflight').first().json;
const PLATFORM = /(youtube|youtu\.be|spotify|apple|instagram|facebook|tiktok|twitter|x\.com|linkedin|linktr\.ee|beacons|patreon|amzn|amazon|bit\.ly|google|discord|substack|medium\.com|calendly)/i;
const NOISE = ['youtube.com', 'youtu.be', 'podcasts.apple.com', 'open.spotify.com', 'music.amazon.com', 'pinterest.com',
  'tiktok.com', 'instagram.com', 'facebook.com', 'x.com', 'twitter.com', 'sotwe.com', 'twstalker.com', 'idcrawl.com'];

const eligible = $input.all()
  .map(i => i.json)
  .filter(l => l.channel_id && ['QUALIFIED', 'RESEARCHED'].includes(String(l.pipeline_stage || '').trim()))
  .sort((a, b) => (String(a.last_error_code || '').startsWith('RESEARCH_') ? 1 : 0) - (String(b.last_error_code || '').startsWith('RESEARCH_') ? 1 : 0)
    || (Number(b.pre_score) || 0) - (Number(a.pre_score) || 0)
    || String(a.first_seen_at || '').localeCompare(String(b.first_seen_at || '')));

const byTavily = Math.floor(budget.remaining.tavily_credits / C.tavily_credits_per_lead);
const byLlm = Math.floor(budget.remaining.llm_usd / C.llm_est_usd_per_call);
const cap = deps.ai_ok ? Math.min(C.max_research_per_run, byTavily, byLlm) : 0;
const selected = eligible.slice(0, cap);
const meta = {
  eligible: eligible.length, selected: selected.length,
  blocked: deps.ai_ok ? '' : 'AI_UNAVAILABLE',
  limited_by_budget: deps.ai_ok && cap < Math.min(C.max_research_per_run, eligible.length),
};
if (!selected.length) return [{ json: { work: false, _meta: meta } }];

const out = [];
for (const lead of selected) {
  // "Jason Bay | CEO @ Outbound Squad" -> "Jason Bay"
  const full = String(lead.channel_name || '').replace(/"/g, '').trim();
  const name = (full.split(/\s[|•·–—-]\s|\s\|\s?/)[0] || full).trim();
  const urls = String(lead.description_excerpt || '').match(/https?:\/\/[^\s)\]]+/gi) || [];
  const site = urls.map(u => (u.match(/^https?:\/\/(?:www\.)?([^\/?#]+)/i) || [])[1] || '').find(h => h && !PLATFORM.test(h)) || '';
  const searches = [
    { query: `"${name}" podcast host`, exclude_domains: NOISE },
    site
      ? { query: `${name} about founder services contact`, include_domains: [site] }
      : { query: `"${name}" podcast official website founder`, exclude_domains: NOISE },
  ];
  searches.forEach((s, q) => out.push({ json: {
    work: true,
    channel_id: lead.channel_id,
    q_index: q,
    site,
    body: { ...s, search_depth: 'basic', max_results: 5, include_raw_content: true },
  } }));
}
out[0].json._meta = meta;
return out;

// 3.5 Build Evidence (OpenAI Version)
const plans = $('3.2 Plan Research').all();
const planFor = i => {
  try { const m = $('3.2 Plan Research').itemMatching(i); if (m) return m.json; } catch (e) { }
  return plans[i].json;
};

const failText = e => [e.description, e.message, e.cause && e.cause.message].filter(Boolean).join(' ').replace(/\s+/g, ' ');
const statusOf = e => Number((String(e.cause?.message || '').match(/^(\d{3})/) || String(e.message || '').match(/\b([45]\d\d)\b/) || [])[1]) || 0;
const results = $input.all().map(i => i.json);
const failed = results.filter(r => r.error);
const hard = failed.find(r => [401, 432, 433].includes(statusOf(r.error)) || /invalid api key|unauthori[sz]ed|usage limit|plan limit/i.test(failText(r.error)));
if (hard || (results.length >= 2 && failed.length === results.length)) {
  throw new Error(`TAVILY_UNAVAILABLE: ${failText((hard || failed[0]).error).slice(0, 240)}`);
}

const leads = new Map($('3.1 Read Leads').all().map(i => [i.json.channel_id, i.json]));
const host = u => ((String(u).toLowerCase().match(/^https?:\/\/(?:www\.)?([^\/?#:]+)/) || [])[1] || '');
const LOGIN_WALLED = /(^|\.)(linkedin\.com|facebook\.com|instagram\.com|x\.com|twitter\.com)$/;
const JUNK = /(^|\.)(gridinsoft\.com|sotwe\.com|twstalker\.com|idcrawl\.com|sitelike\.org|siteprice\.org|similarsites\.com|scamadviser\.com|urlscan\.io|whois\.com)$/;

const cleanMarkdown = t => String(t || '')
  .replace(/!\[[^\]]*\]\([^)]*\)/g, ' ')
  .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1')
  .replace(/\(\/\/[^)\s]+\)|https?:\/\/\S+\.(png|jpe?g|gif|svg|webp)\S*/gi, ' ')
  .replace(/[#*_>`|]+/g, ' ');
const SIGNAL = /\b(founder|co-?founder|ceo|owner|managing partner|president|host(?:ed)? by|we help|we work with|our clients|services|pricing|book a (?:call|demo)|work with (?:us|me)|consulting|coaching|agency|contact|email|based in|located in|headquartered)\b|[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/gi;
const LIMIT = 7000, PAGE_CHARS = 1300, SNIPPET_CHARS = 300, SNIPPET_BUDGET = 1200;

function signalText(text, max) {
  const t = cleanMarkdown(text).replace(/\s+/g, ' ').trim();
  if (t.length <= max) return t;
  const spans = [[0, 240]];
  SIGNAL.lastIndex = 0;
  let m;
  while ((m = SIGNAL.exec(t)) && spans.length < 12) spans.push([Math.max(0, m.index - 160), Math.min(t.length, m.index + 260)]);
  spans.sort((a, b) => a[0] - b[0]);
  const merged = [];
  for (const s of spans) {
    const last = merged[merged.length - 1];
    if (last && s[0] <= last[1]) last[1] = Math.max(last[1], s[1]); else merged.push([...s]);
  }
  return merged.map(([a, b]) => t.slice(a, b)).join(' … ').slice(0, max);
}

const groups = new Map();
results.forEach((res, i) => {
  const plan = planFor(i);
  const g = groups.get(plan.channel_id) || { ok: 0, failed: 0, site: plan.site, results: new Map() };
  groups.set(plan.channel_id, g);
  if (res.error) { g.failed++; return; }
  g.ok++;
  for (const r of res.results || []) {
    if (!r.url) continue;
    const prev = g.results.get(r.url);
    if (!prev || (r.score || 0) > (prev.score || 0)) g.results.set(r.url, r);
  }
});

const ENUM = values => ({ type: 'string', enum: values });
const schema = {
  name: "evidence_extraction",
  strict: true,
  schema: {
    type: 'object',
    properties: {
      host_name: { type: 'string', description: 'Full name of the host(s) or "Unknown"' },
      host_role: { type: 'string', description: 'Host job title, e.g. Founder, CEO, Coach, or "Unknown"' },
      business_name: { type: 'string', description: 'Company or brand behind the show, or "Unknown"' },
      business_website: { type: 'string', description: 'Primary business URL that appears in the evidence, or "Unknown"' },
      offer_summary: { type: 'string', description: 'One sentence: what the business sells, or "Unknown"' },
      offer_quote: { type: 'string', description: 'Exact words copied from the evidence that prove the offer, or ""' },
      business_model_type: ENUM(['B2B_SERVICES', 'COACHING_CONSULTING', 'SAAS_TECH', 'ECOMMERCE', 'SPONSORSHIP_MEDIA', 'NON_MONETIZED', 'UNKNOWN']),
      on_camera: ENUM(['YES', 'NO', 'UNKNOWN']),
      country_code: { type: 'string', description: 'ISO 3166-1 alpha-2 code of where the host/business is based, or "UNKNOWN"' },
      geo_quote: { type: 'string', description: 'Exact words copied from the evidence that prove the location, or ""' },
      primary_language: { type: 'string', description: 'ISO 639-1 code of the language the show is in, or "UNKNOWN"' },
      production_credit: { type: 'string', description: 'Named agency, studio or editor credited for producing or clipping the show, or "None"' },
      public_profiles: { type: 'array', items: { type: 'string' }, description: 'LinkedIn / X profile URLs of the host found in the evidence' },
      contact_route_type: ENUM(['EMAIL', 'CONTACT_FORM', 'LINKEDIN', 'UNKNOWN']),
      contact_route_url: { type: 'string', description: 'Email address or contact URL found in the evidence, or "Unknown"' },
      other_platform_shortform: { type: 'string', description: 'Evidence of TikTok / Reels / Shorts activity elsewhere, or "Unknown"' },
      evidence_urls: { type: 'array', items: { type: 'string' }, description: 'URLs from the evidence pack you relied on' },
      contradictions: { type: 'string', description: 'Conflicting facts in the evidence, or "None"' },
      research_confidence: ENUM(['HIGH', 'MEDIUM', 'LOW']),
    },
    required: ['host_name', 'host_role', 'business_name', 'business_website', 'offer_summary', 'offer_quote',
      'business_model_type', 'on_camera', 'country_code', 'geo_quote', 'primary_language', 'production_credit',
      'public_profiles', 'contact_route_type', 'contact_route_url', 'other_platform_shortform', 'evidence_urls',
      'contradictions', 'research_confidence'],
    additionalProperties: false
  }
};

const SYSTEM = 'You are a meticulous B2B research analyst. You extract facts about the business behind a YouTube podcast '
  + 'using ONLY the evidence pack you are given. If a fact is not explicitly stated there, answer "Unknown" (or the enum UNKNOWN). '
  + 'Never infer, never guess, never use outside knowledge. Quotes must be copied word-for-word from the evidence pack. '
  + 'Absence of evidence is not evidence: use NON_MONETIZED only if the evidence explicitly shows there is no business or offer.';

return [...groups.entries()].map(([cid, g]) => {
  const lead = leads.get(cid) || { channel_id: cid };
  const full = String(lead.channel_name || '');
  const tokens = [full, full.split(/\s[|•·–—-]\s|\s\|\s?/)[0], String(lead.handle || '').replace(/^@/, ''), g.site]
    .map(s => String(s || '').toLowerCase().trim()).filter(s => s.length >= 4);

  const relevant = r => {
    if (JUNK.test(host(r.url))) return false;
    if (g.site && host(r.url).endsWith(g.site)) return true;
    const hay = `${r.title || ''} ${r.content || ''} ${(r.raw_content || '').slice(0, 20000)}`.toLowerCase();
    return tokens.some(t => hay.includes(t));
  };

  const ranked = [...g.results.values()].filter(relevant)
    .sort((a, b) => (g.site && host(b.url).endsWith(g.site) ? 1 : 0) - (g.site && host(a.url).endsWith(g.site) ? 1 : 0) || (b.score || 0) - (a.score || 0));
  const pages = ranked.filter(r => r.raw_content && !LOGIN_WALLED.test(host(r.url))).slice(0, 4);

  const parts = [
    '=== YOUTUBE CHANNEL (first-party) ===',
    `Channel: ${lead.channel_name || 'Unknown'} | ${lead.channel_url || ''}`,
    `Handle: ${lead.handle || 'Unknown'} | Country tag: ${lead.country || 'none'} | Language tag: ${lead.default_language || 'none'}`,
    `Description: ${lead.description_excerpt || 'none'}`,
    '',
    '=== WEB PAGES ===',
    ...(pages.length ? pages.map(p => `[SOURCE ${p.url}] ${p.title || ''}\n${signalText(p.raw_content, PAGE_CHARS)}\n`) : ['No relevant pages found.']),
    '',
    '=== SEARCH SNIPPETS ===',
    ranked.filter(r => r.content && !pages.includes(r)).slice(0, 6)
      .map(r => `[SNIPPET ${r.url}] ${cleanMarkdown(r.content).replace(/\s+/g, ' ').trim().slice(0, SNIPPET_CHARS)}`)
      .join('\n').slice(0, SNIPPET_BUDGET) || 'No snippets.',
  ];

  const pack = parts.join('\n').slice(0, LIMIT);
  return { json: {
    channel_id: cid,
    lead,
    evidence_pack: pack,
    valid_urls: [lead.channel_url, ...ranked.map(r => r.url)].filter(Boolean),
    pages_used: pages.length,
    results_dropped: g.results.size - ranked.length,
    searches_ok: g.ok,
    searches_failed: g.failed,
    llm_request: {
      model: $('0.5 Preflight').first().json.config.llm_model,
      messages: [
        { role: "system", content: SYSTEM },
        { role: "user", content: `Podcast channel: "${lead.channel_name}"\n\nEVIDENCE PACK:\n${pack}` }
      ],
      temperature: 0.1,
      max_tokens: 4096,
      response_format: { type: "json_schema", json_schema: schema }
    },
  } };
});

// 3.7 Validate Evidence (OpenAI Version)
const { config: C } = $('0.5 Preflight').first().json;

const failText = e => [e.description, e.message, e.cause && e.cause.message].filter(Boolean).join(' ').replace(/\s+/g, ' ');
const statusOf = e => Number((String(e.cause?.message || '').match(/^(\d{3})/) || String(e.message || '').match(/\b([45]\d\d)\b/) || [])[1]) || 0;
const calls = $input.all().map(i => i.json);
const failed = calls.filter(r => r.error);
const hard = failed.find(r => { const s = statusOf(r.error); return s >= 400 && s < 500 && s !== 429; });
if (hard || (calls.length >= 2 && failed.length === calls.length)) {
  throw new Error(`OPENAI_UNAVAILABLE: ${failText((hard || failed[0]).error).slice(0, 240)}`);
}

const packs = $('3.5 Build Evidence').all();
const packFor = i => {
  try { const m = $('3.5 Build Evidence').itemMatching(i); if (m) return m.json; } catch (e) { }
  return packs[i].json;
};
const U = 'Unknown';
const isUnknown = v => v == null || (Array.isArray(v) && !v.length)
  || /^(unknown|n\/?a|none|null|nil|-|unspecified|not (found|available|specified|mentioned|stated|provided))?$/i.test(String(v).trim());
const clean = v => (isUnknown(v) ? U : String(v).trim());
const norm = s => String(s || '').toLowerCase().replace(/[^a-z0-9@.]+/g, ' ').replace(/\s+/g, ' ').trim();
const host = u => ((String(u).toLowerCase().match(/^(?:https?:\/\/)?(?:www\.)?([^\/?#:\s]+)/) || [])[1] || '');
const PLATFORMS = ['youtube.com', 'youtu.be', 'linkedin.com', 'twitter.com', 'x.com', 'instagram.com', 'facebook.com', 'tiktok.com'];

return calls.map((res, i) => {
  const p = packFor(i);
  const evidence = String(p.evidence_pack || '').toLowerCase();
  const evidenceNorm = norm(evidence);
  const allowed = new Set((p.valid_urls || []).map(u => String(u).toLowerCase().replace(/\/+$/, '')));
  const inPack = v => { const s = norm(v); return s.length >= 3 && evidenceNorm.includes(s); };
  const quoted = q => { const s = norm(q); return s.length >= 8 && evidenceNorm.includes(s); };
  const urlOk = u => {
    if (isUnknown(u)) return false;
    const n = String(u).toLowerCase().trim().replace(/\/+$/, '');
    if (allowed.has(n) || evidence.includes(n.replace(/^https?:\/\/(www\.)?/, ''))) return true;
    const h = host(n);
    return !!h && !PLATFORMS.includes(h) && evidence.includes(h);
  };
  const warnings = [];

  // ---- 1. Model response (OpenAI) ----
  const choice = res.choices?.[0];
  const text = choice?.message?.content || '';
  const usage = res.usage || {};
  const tokensIn = Number(usage.prompt_tokens) || 0;
  const tokensOut = Number(usage.completion_tokens) || 0;

  let failure = '';
  let f = {};
  if (res.error) failure = 'LLM_FAILED';
  else if (choice?.finish_reason === 'content_filter') failure = 'LLM_BLOCKED';
  else if (choice?.finish_reason === 'length') failure = 'LLM_TRUNCATED';
  else { try { f = JSON.parse(text); } catch (e) { failure = 'LLM_BAD_JSON'; } }
  if (failure) warnings.push(failure + (res.error ? `: ${failText(res.error).slice(0, 120)}` : ''));

  // ---- 2. Grounding ----
  let host_name = clean(f.host_name);
  if (host_name !== U) {
    const last = host_name.split(/[\s&,]+/).filter(w => w.length > 2).pop();
    if (!inPack(host_name) && !(last && inPack(last))) { warnings.push(`host_name not in evidence (${host_name})`); host_name = U; }
  }
  let host_role = host_name === U ? U : clean(f.host_role);
  if (host_role !== U && !(host_role.toLowerCase().match(/[a-z]{4,}/g) || []).some(w => evidence.includes(w))) host_role = U;

  let business_name = clean(f.business_name);
  if (business_name !== U) {
    const core = business_name.replace(/[,.]?\s+(llc|inc|ltd|limited|co|corp|gmbh|plc)\.?$/i, '');
    if (!inPack(business_name) && !inPack(core)) { warnings.push(`business_name not in evidence (${business_name})`); business_name = U; }
  }
  let business_website = clean(f.business_website);
  if (business_website !== U && !urlOk(business_website)) { warnings.push(`website not in evidence (${business_website})`); business_website = U; }

  let offer_summary = clean(f.offer_summary);
  if (offer_summary !== U && !quoted(f.offer_quote)) { warnings.push('offer has no supporting quote'); offer_summary = U; }

  let country = String(f.country_code || '').trim().toUpperCase();
  if (!/^[A-Z]{2}$/.test(country) || !quoted(f.geo_quote)) country = 'UNKNOWN';
  const language = /^[a-z]{2}$/i.test(String(f.primary_language || '').trim()) ? String(f.primary_language).trim().toLowerCase() : 'UNKNOWN';

  let contact_route_url = clean(f.contact_route_url);
  if (contact_route_url !== U) {
    const ok = /@/.test(contact_route_url) && !/^https?:/i.test(contact_route_url) ? evidence.includes(contact_route_url.toLowerCase()) : urlOk(contact_route_url);
    if (!ok) { warnings.push(`contact not in evidence (${contact_route_url})`); contact_route_url = U; }
  }
  let contact_route_type = String(f.contact_route_type || '').toUpperCase();
  if (contact_route_url === U || !['EMAIL', 'CONTACT_FORM', 'LINKEDIN'].includes(contact_route_type)) contact_route_type = 'UNKNOWN';

  const profiles = (Array.isArray(f.public_profiles) ? f.public_profiles : []).filter(urlOk);
  const evidence_urls = [...new Set((Array.isArray(f.evidence_urls) ? f.evidence_urls : []).filter(urlOk))];

  let production_credit = isUnknown(f.production_credit) ? 'None' : String(f.production_credit).trim();
  if (production_credit !== 'None' && !(production_credit.toLowerCase().match(/[a-z]{4,}/g) || []).some(w => evidence.includes(w))) production_credit = 'None';

  const MODELS = ['B2B_SERVICES', 'COACHING_CONSULTING', 'SAAS_TECH', 'ECOMMERCE', 'SPONSORSHIP_MEDIA', 'NON_MONETIZED'];
  let model = String(f.business_model_type || '').toUpperCase();
  if (!MODELS.includes(model)) model = 'UNKNOWN';
  const businessFacts = [business_name, business_website, offer_summary].filter(v => v !== U).length;
  if (model === 'NON_MONETIZED' && (p.pages_used < 2 || f.research_confidence === 'LOW')) {
    warnings.push('NON_MONETIZED claim on thin evidence -> UNKNOWN'); model = 'UNKNOWN';  
  } else if (model !== 'UNKNOWN' && model !== 'NON_MONETIZED' && !businessFacts) {
    warnings.push(`business model ${model} has no supporting facts -> UNKNOWN`); model = 'UNKNOWN';
  }
  const on_camera = ['YES', 'NO'].includes(String(f.on_camera).toUpperCase()) ? String(f.on_camera).toUpperCase() : 'UNKNOWN';

  // ---- 3. Confidence ----
  const core = { host_name, business_name, business_website, offer_summary, business_model_type: model };
  const unknowns = Object.entries(core).filter(([, v]) => v === U || v === 'UNKNOWN').map(([k]) => k);
  let research_confidence = ['HIGH', 'MEDIUM', 'LOW'].includes(f.research_confidence) ? f.research_confidence : 'LOW';
  if (failure || unknowns.length >= 3 || warnings.length >= 3) research_confidence = 'LOW';
  else if (unknowns.length && research_confidence === 'HIGH') research_confidence = 'MEDIUM';

  const cost = (tokensIn * C.llm_usd_per_m_input + tokensOut * C.llm_usd_per_m_output) / 1e6;
  return { json: {
    ...p.lead,
    host_name, host_role, business_name, business_website, offer_summary,
    business_model_type: model,
    on_camera,
    us_evidence: country === 'UNKNOWN' ? U : `${country}: ${String(f.geo_quote).slice(0, 120)}`,
    language_evidence: language === 'UNKNOWN' ? U : language,
    production_credit,
    public_profiles: profiles.join(', ') || U,
    contact_route_type, contact_route_url,
    other_platform_shortform: clean(f.other_platform_shortform),
    evidence_urls: evidence_urls.join(', ') || 'None',
    contradictions: isUnknown(f.contradictions) ? 'None' : String(f.contradictions).trim(),
    unknowns: unknowns.join(', ') || 'None',
    warnings: warnings.join(' | ') || 'None',
    research_confidence,
    research_at: DateTime.now().toUTC().toISO(),
    tavily_credits: p.searches_ok,
    llm_cost_est_usd: +cost.toFixed(5),
    _research: { failure, results_dropped: p.results_dropped, country_code: country, language, pages_used: p.pages_used, tokens_in: tokensIn, tokens_out: tokensOut, cost_usd: cost, searches_failed: p.searches_failed },
  } };
});

// 3.8 Score Lead
// Pure decision function for Phase 3: post-research gates (4b geo/language, 5 monetisation, 7 existing
// agency) and the 100-point rubric. Signals the system cannot observe (e.g. "on camera", which needs a
// human to watch the video) lower the score and raise a review flag instead of auto-rejecting.
// A failed research call is a strike, not a verdict: strike 1 keeps the lead QUALIFIED for the next run,
// strike 2 parks it in NEEDS_INFO.
const { config: C, run } = $('0.5 Preflight').first().json;
const U = 'Unknown';
const now = Date.now();
const plusDays = d => DateTime.fromMillis(now).setZone('America/Los_Angeles').plus({ days: d }).toISODate();
const num = (v, d = 0) => { const s = String(v ?? '').trim(); const n = Number(s); return s !== '' && Number.isFinite(n) ? n : d; };
const gapScore = g => ({ STRONG: 30, MODERATE: 18 }[g] ?? 5);
const consistencyScore = (long60, maxGap) =>
  long60 >= 8 && maxGap <= 14 ? 15 : long60 >= 4 && maxGap <= 21 ? 12 : long60 >= 2 ? 8 : 5;
function settle(outcome, retries, recheckDays) {
  if (outcome === 'REVIEW') return { pipeline_stage: 'SCORED', recheck_after: '' };
  if (outcome === 'RETRY') return { pipeline_stage: 'QUALIFIED', recheck_after: '' };
  if (outcome === 'REJECTED') return { pipeline_stage: 'CLOSED_REJECTED', recheck_after: '' };
  const canRecheck = retries < C.max_rechecks;
  return { pipeline_stage: outcome === 'NURTURE' ? 'CLOSED_NURTURE' : 'NEEDS_INFO', recheck_after: canRecheck ? plusDays(recheckDays) : '' };
}

return $input.all().map(({ json: d }) => {
  const R = d._research || {};
  const known = v => v && v !== U;
  const model = String(d.business_model_type || 'UNKNOWN');
  const onCamera = String(d.on_camera || 'UNKNOWN');
  const medianMins = num(d.median_longform_minutes);

  // ---- Rubric (100) ----
  const score_gap = num(d.score_gap, gapScore(String(d.gap_class || '').toUpperCase()));
  const score_consistency = num(d.score_consistency, consistencyScore(num(d.longform_60d), num(d.max_gap_longform_60d, 60)));
  const score_icp = { B2B_SERVICES: 20, COACHING_CONSULTING: 20, SAAS_TECH: 20, ECOMMERCE: 14, SPONSORSHIP_MEDIA: 8, NON_MONETIZED: 0 }[model] ?? 5;
  const hasOffer = known(d.offer_summary), hasSite = known(d.business_website);
  const score_monetization = hasOffer && hasSite ? 15 : hasOffer || hasSite ? 8 : 0;
  const score_footage = onCamera === 'YES' ? (medianMins >= 20 ? 10 : medianMins >= 10 ? 8 : 2)
    : onCamera === 'NO' ? 0 : (medianMins >= 20 ? 6 : 2);
  const hasHost = known(d.host_name);
  const decisionMaker = /founder|ceo|owner|partner|president|principal|director|coach/i.test(String(d.host_role || ''));
  const hasContact = known(d.contact_route_url) && d.contact_route_type !== 'UNKNOWN';
  const score_decision = (hasHost ? (decisionMaker ? 5 : 3) : 0) + (hasContact ? 5 : 0);
  const score_total = score_gap + score_consistency + score_icp + score_monetization + score_footage + score_decision;

  // ---- Gates ----
  let outcome = 'REVIEW', rule = 'PASSED', code = 'QUALIFIED_FOR_REVIEW', text = '', recheckDays = 0;
  const set = (o, r, c, t, days = 0) => { outcome = o; rule = r; code = c; text = t; recheckDays = days; };
  const gates = [];
  const credit = String(d.production_credit || 'None');
  const AGENCY = /\b(produced|edited|clipped|managed|powered)\s+by\b|\bagency\b|\bclipping\b|\bproduction (company|partner|house|team)\b/i;

  const struck = String(d.last_error_code || '').startsWith('RESEARCH_');
  if (R.failure && !struck) {
    set('RETRY', 'Research', 'RESEARCH_RETRY', `Research failed (${R.failure}); retried next run`);
  } else if (R.failure) {
    set('NEEDS_INFO', 'Research', 'RESEARCH_FAILED', `Research failed twice (${R.failure})`, C.needs_info_recheck_days);
  } else if (R.country_code && R.country_code !== 'UNKNOWN' && !C.allowed_countries_list.includes(R.country_code)) {
    set('REJECTED', 'Gate 4b', 'GEO_BLOCKED', `Gate 4b: evidence places the business in ${R.country_code}`); gates.push('GATE_4B_FAIL');
  } else if (R.language && R.language !== 'UNKNOWN' && !C.allowed_languages_list.includes(R.language)) {
    set('REJECTED', 'Gate 4b', 'LANGUAGE_BLOCKED', `Gate 4b: show language is ${R.language}`); gates.push('GATE_4B_FAIL');
  } else {
    gates.push('GATE_4B_PASS');
    if (model === 'NON_MONETIZED') {
      set('REJECTED', 'Gate 5', 'NO_MONETIZATION', 'Gate 5: evidence shows no business or offer behind the show'); gates.push('GATE_5_FAIL');
    } else if (!known(d.business_name) && !hasSite && !hasOffer && d.research_confidence === 'LOW') {
      set('NEEDS_INFO', 'Gate 5', 'INSUFFICIENT_RESEARCH_DATA', 'Gate 5: no business, website or offer could be verified', C.needs_info_recheck_days); gates.push('GATE_5_NEEDS_INFO');
    } else {
      gates.push('GATE_5_PASS');
      if (credit !== 'None' && AGENCY.test(credit)) {
        set('REJECTED', 'Gate 7', 'EXISTING_AGENCY', `Gate 7: already works with a production vendor (${credit})`); gates.push('GATE_7_FAIL');
      } else {
        gates.push('GATE_7_PASS');
      }
    }
  }

  let tier = '';
  if (outcome === 'REVIEW') {
    if (score_total >= C.tier_a_min) tier = 'A';
    else if (score_total >= C.tier_b_min) tier = 'B';
    else set('NURTURE', 'Score Threshold', 'LOW_TOTAL_SCORE', `Score ${score_total}/100 below review threshold ${C.tier_b_min}`, C.nurture_recheck_days);
  }
  if (outcome === 'REVIEW') text = `Tier ${tier}: ${score_total}/100`;

  const reasons = [hasSite && 'Verified Website', hasOffer && 'Verified Offer', hasHost && 'Verified Host', hasContact && 'Verified Contact'].filter(Boolean);
  const noContradictions = /^(none|)$/i.test(String(d.contradictions || 'None').trim());
  const confidence = reasons.length >= 3 && noContradictions ? 'HIGH' : reasons.length >= 2 ? 'MEDIUM' : 'LOW';
  const flags = [];
  if (onCamera !== 'YES') flags.push('VERIFY_FOOTAGE');
  if (d.shorts_review_flag === 'TRUE') flags.push('VERIFY_SHORTS_TAB');
  const state = settle(outcome, num(d.retry_count), recheckDays);
  const score_basis = `Gap ${score_gap}/30 | Consistency ${score_consistency}/15 | ICP ${score_icp}/20 | Monetization ${score_monetization}/15 | Footage ${score_footage}/10 | Decision-maker ${score_decision}/10`;

  const scored = outcome !== 'RETRY';
  return { json: {
    ...d,
    tier, confidence,
    score_total: scored ? score_total : '',
    score_gap, score_consistency, score_icp, score_monetization, score_footage, score_decision,
    score_basis,
    confidence_reasons: reasons.join(', ') || 'No verified signals',
    gate_results: [String(d.gate_results || '').trim(), ...gates].filter(Boolean).join(', '),
    reason_code: code,
    reason_text: text,
    warnings: [d.warnings !== 'None' ? d.warnings : '', flags.join(', ')].filter(Boolean).join(' | ') || 'None',
    ...state,
    last_error_code: R.failure ? `RESEARCH_${R.failure}` : '',
    last_updated_at: run.started_at,
    last_run_id: run.run_id,
    _log: outcome === 'REJECTED' || outcome === 'NURTURE' ? {
      type: outcome, rule, reason_code: code, reason_text: text, confidence,
      evidence_text: (d.evidence_urls && d.evidence_urls !== 'None' ? d.evidence_urls : score_basis).slice(0, 500),
      score_total, recheck_after: state.recheck_after, rejected_by: 'RULES_PHASE_3',
    } : null,
    _decision: { outcome, rule },
  } };
});

// 4.2 Plan Notes (OpenAI Version)
const { config: C, budget, deps } = $('0.5 Preflight').first().json;
let researchSpend = 0;
try {
  if ($('3.7 Validate Evidence').isExecuted) researchSpend =$('3.7 Validate Evidence').all().reduce((s, i) => s + (Number(i.json._research?.cost_usd) || 0), 0);
} catch (e) { }
const byLlm = Math.floor(Math.max(0, budget.remaining.llm_usd - researchSpend) / C.llm_est_usd_per_call);

const eligible = $input.all().map(i => i.json)
  .filter(l => l.channel_id && String(l.pipeline_stage || '').trim() === 'SCORED')
  .sort((a, b) => String(a.tier || 'Z').localeCompare(String(b.tier || 'Z')) || (Number(b.score_total) || 0) - (Number(a.score_total) || 0));
const cap = deps.ai_ok ? Math.min(C.max_notes_per_run, byLlm) : 0;
const selected = eligible.slice(0, cap);
const meta = { eligible: eligible.length, selected: selected.length, blocked: deps.ai_ok ? '' : 'AI_UNAVAILABLE',
  limited_by_budget: deps.ai_ok && byLlm < Math.min(C.max_notes_per_run, eligible.length) };
if (!selected.length) return [{ json: { work: false, _meta: meta } }];

const known = v => v !== undefined && v !== null && String(v).trim() !== '' && !/^unknown$/i.test(String(v).trim());
const SYSTEM = 'You write short internal briefing notes for a sales reviewer at Podsplicer, a service that turns long-form '
  + 'podcast episodes into YouTube Shorts. Use only the facts given. Never invent topics, guests, numbers or praise. '
  + 'You must respond in valid JSON format containing a single key "note".';

return selected.map((l, idx) => {
  const facts = [
    ['Channel', l.channel_name],
    ['Host', known(l.host_name) ? `${l.host_name}${known(l.host_role) ? ` (${l.host_role})` : ''}` : ''],
    ['Business', known(l.business_name) ? `${l.business_name}${known(l.business_website) ? ` - ${l.business_website}` : ''}` : ''],
    ['Offer', known(l.offer_summary) ? l.offer_summary : ''],
    ['Business model', known(l.business_model_type) ? l.business_model_type : ''],
    ['Last 60 days', `${l.longform_60d} long-form episodes (median ${l.median_longform_minutes} min), ${l.shortcand_60d} Shorts`],
    ['Shorts gap', `${l.gap_class} (ratio ${l.shorts_ratio_60d || 0} Shorts per episode)`],
    ['Score', `Tier ${l.tier}, ${l.score_total}/100`],
    ['Contact route', known(l.contact_route_url) ? `${l.contact_route_type}: ${l.contact_route_url}` : ''],
  ].filter(([, v]) => v).map(([k, v]) => `- ${k}: ${v}`).join('\n');

  const prompt = `Write a briefing note of at most 90 words in exactly 3 sentences:\n`
    + `1) who runs the show and what their business sells; 2) the Shorts gap, citing the 60-day numbers; `
    + `3) the most promising outreach angle given the business model and contact route.\n`
    + `Do not mention facts that are missing. No flattery, no clichés ("love your channel", "big fan", "game changer").\n\nFACTS:\n${facts}`;

  const json = {
    work: true,
    lead: l,
    llm_request: {
      model: $('0.5 Preflight').first().json.config.llm_model,
      messages: [
        { role: 'system', content: SYSTEM },
        { role: 'user', content: prompt }
      ],
      temperature: 0.3,
      max_tokens: 1024,
      response_format: { type: 'json_object' }
    },
  };
  if (idx === 0) json._meta = meta;
  return { json };
});

// 4.5 Validate Note (OpenAI Version)
const { config: C, run } = $('0.5 Preflight').first().json;

const failText = e => [e.description, e.message, e.cause && e.cause.message].filter(Boolean).join(' ').replace(/\s+/g, ' ');
const statusOf = e => Number((String(e.cause?.message || '').match(/^(\d{3})/) || String(e.message || '').match(/\b([45]\d\d)\b/) || [])[1]) || 0;
const calls = $input.all().map(i => i.json);
const failed = calls.filter(r => r.error);
const hard = failed.find(r => { const s = statusOf(r.error); return s >= 400 && s < 500 && s !== 429; });
if (hard || (calls.length >= 2 && failed.length === calls.length)) {
  throw new Error(`OPENAI_UNAVAILABLE: ${failText((hard || failed[0]).error).slice(0, 240)}`);
}

const plans = $('4.2 Plan Notes').all();
const planFor = i => {
  try { const m = $('4.2 Plan Notes').itemMatching(i); if (m) return m.json; } catch (e) { }
  return plans[i].json;
};
const BANNED = ['love your channel', 'love the channel', 'love your podcast', 'love the show', 'big fan', 'huge fan',
  'stumbled across', 'stumbled upon', 'hope this finds you well', 'game changer', 'game-changer', 'synergy', 'reaching out because'];

return calls.map((res, i) => {
  const l = planFor(i).lead;

  // OpenAI Parsing Logic
  const choice = res.choices?.[0];
  const text = choice?.message?.content || '';
  const usage = res.usage || {};
  const tokensIn = Number(usage.prompt_tokens) || 0;
  const tokensOut = Number(usage.completion_tokens) || 0;

  let note = '';
  const flags = [];
  if (res.error) flags.push(`LLM_FAILED: ${res.error.message || 'Unknown'}`);
  else if (choice?.finish_reason === 'length') flags.push('LLM_TRUNCATED');
  else { try { note = String(JSON.parse(text).note || '').replace(/\s+/g, ' ').trim(); } catch (e) { flags.push('LLM_BAD_JSON'); } }

  const words = note ? note.split(' ').length : 0;
  if (note) {
    if (words > 90) flags.push(`TOO_LONG_${words}_WORDS`);
    if (words < 20) flags.push(`TOO_SHORT_${words}_WORDS`);
    const lower = note.toLowerCase();
    for (const b of BANNED) if (lower.includes(b)) flags.push(`BANNED:${b}`);
    if (/\bunknown\b/i.test(note)) flags.push('MENTIONS_UNKNOWN');
  }
  const note_status = !note ? 'FAILED' : flags.length ? 'NEEDS_EDIT' : 'READY';
  const warnings = [l.warnings && l.warnings !== 'None' ? l.warnings : '', flags.length ? `NOTE: ${flags.join(', ')}` : ''].filter(Boolean).join(' | ') || 'None';

  return { json: {
    channel_id: l.channel_id,
    queued_at: DateTime.now().toUTC().toISO(),
    tier: l.tier, score_total: l.score_total, confidence: l.confidence,
    channel_name: l.channel_name, channel_url: l.channel_url,
    rep_video_1: l.rep_video_1, rep_video_2: l.rep_video_2, rep_video_3: l.rep_video_3,
    shorts_tab_url: l.shorts_tab_url, subscriber_count: l.subscriber_count,
    longform_60d: l.longform_60d, shortcand_60d: l.shortcand_60d, shorts_ratio_60d: l.shorts_ratio_60d,
    gap_class: l.gap_class, gap_confidence: l.gap_confidence, shorts_review_flag: l.shorts_review_flag,
    component_scores: l.score_basis, gate_results: l.gate_results,
    host_name: l.host_name, host_role: l.host_role, business_name: l.business_name,
    business_website: l.business_website, offer_summary: l.offer_summary, on_camera: l.on_camera,
    public_profiles: l.public_profiles, contact_route_url: l.contact_route_url, evidence_urls: l.evidence_urls,
    personalization_note: note,
    note_status,
    warnings,
    _note: { tokens_in: tokensIn, tokens_out: tokensOut, cost_usd: (tokensIn * C.llm_usd_per_m_input + tokensOut * C.llm_usd_per_m_output) / 1e6, failed: !note },
  } };
});

// 5.1 Summarise Run
// Builds the Run Log row from what this execution actually did (node outputs): the funnel, real
// YouTube units, Tavily credits, Gemini tokens and cost.
//   SUCCESS   everything ran
//   PARTIAL   some items failed (counted in item_errors) - nothing to do
//   DEGRADED  a dependency was unavailable and phases were skipped - needs a human (heartbeat goes down)
const { run, budget, deps, warnings: preflightWarnings } = $('0.5 Preflight').first().json;
const ran = n => { try { return $(n).isExecuted; } catch (e) { return false; } };
const rows = n => (ran(n) ? $(n).all().map(i => i.json) : []);
const work = n => rows(n).filter(j => j.work === true);
const meta = n => (rows(n)[0] || {})._meta || {};
const count = (arr, f) => arr.filter(f).length;
const sum = (arr, f) => arr.reduce((s, x) => s + (Number(f(x)) || 0), 0);

// ---- Phase 1: discover ----
const calls = ran('1.8 Query YouTube') ? work('1.6 Plan Discovery') : [];
const searchCalls = count(calls, p => p.kind === 'SEARCH');
const seedCalls = count(calls, p => p.kind === 'SEED');
const disc = (rows('1.9 Collect Candidates')[0] || {})._stats || {};
const registered = rows('1.14 Register Leads').length;
const rechecked = rows('1.4 Requeue Leads').length;

// ---- Phase 2: screen & measure ----
const p2 = rows('2.11 Decide Qualification');
const screened = rows('2.5 Screen Channels');
const measured = count(screened, s => s.work === true);
const ytEnrich = rows('2.4 Fetch Channels').length + rows('2.8 Fetch Uploads').length + rows('2.10 Fetch Videos').length;
const by2 = (outcome, rule) => count(p2, d => d._decision?.outcome === outcome && (!rule || d._decision?.rule === rule));

// ---- Phase 3: research & score ----
const p3r = rows('3.7 Validate Evidence');
const p3 = rows('3.8 Score Lead');
const by3 = (outcome, rule) => count(p3, d => d._decision?.outcome === outcome && (!rule || d._decision?.rule === rule));

// ---- Phase 4: queue ----
const notes = rows('4.5 Validate Note');
const queued = rows('4.7 Mark In Review').length;

// ---- Spend & errors ----
const ytUnits = searchCalls * 100 + seedCalls + ytEnrich;
const tavily = sum(p3r, r => r.tavily_credits);
const tokensIn = sum(p3r, r => r._research?.tokens_in) + sum(notes, n => n._note?.tokens_in);
const tokensOut = sum(p3r, r => r._research?.tokens_out) + sum(notes, n => n._note?.tokens_out);
const llmUsd = sum(p3r, r => r._research?.cost_usd) + sum(notes, n => n._note?.cost_usd);
const itemErrors = (Number(disc.request_errors) || 0)
  + count(p2, d => /FETCH_FAILED/.test(`${d.missing_fields || ''} ${d.reason_code || ''}`))
  + sum(p3r, r => r._research?.searches_failed)
  + count(p3r, r => r._research?.failure)
  + count(notes, n => n._note?.failed);

const notesOut = [...(preflightWarnings || [])];
notesOut.push(`FUNNEL screened=${screened.length} measured=${measured} qualified=${by2('CONTINUE')} researched=${p3r.length} queued=${queued}`);
if (rechecked) notesOut.push(`RECHECKED=${rechecked}`);
for (const [n, label] of [['1.6 Plan Discovery', 'SEARCH'], ['2.2 Plan Screening', 'SCREEN'], ['3.2 Plan Research', 'RESEARCH'], ['4.2 Plan Notes', 'NOTES']]) {
  if (meta(n).limited_by_budget) notesOut.push(`${label}_LIMITED_BY_BUDGET`);
}
const retries = count(p3, d => d._decision?.outcome === 'RETRY');
if (retries) notesOut.push(`RESEARCH_RETRY_NEXT_RUN=${retries}`);
const needsEdit = count(notes, n => n.note_status !== 'READY');
if (needsEdit) notesOut.push(`NOTES_NEED_EDIT=${needsEdit}`);
if (itemErrors) notesOut.push(`ITEM_ERRORS=${itemErrors}`);

const ended = DateTime.now().toUTC();
const minutes = +(ended.diff(DateTime.fromISO(run.started_at), 'minutes').minutes).toFixed(2);
const status = !deps.ai_ok ? 'DEGRADED' : itemErrors ? 'PARTIAL' : 'SUCCESS';

return [{ json: {
  run_id: run.run_id,
  status,
  ended_at: ended.toISO(),
  candidates_found: Number(disc.candidates_found) || 0,
  duplicates_skipped: Number(disc.already_known) || 0,
  registered,
  enriched: screened.length,
  nurture_rule1: by2('NURTURE', 'Gate 1'),
  nurture_rule2: by2('NURTURE', 'Gate 2'),
  rejected_rule4a: by2('REJECTED', 'Gate 4a'),
  rejected_rule4b: by3('REJECTED', 'Gate 4b'),
  rejected_rule5: by3('REJECTED', 'Gate 5'),
  rejected_rule7: by3('REJECTED', 'Gate 7'),
  needs_info: by2('NEEDS_INFO') + by3('NEEDS_INFO'),
  researched: p3r.length,
  scored: count(p3, d => d._decision?.outcome !== 'RETRY'),
  to_review: queued,
  item_errors: itemErrors,
  yt_search_calls: searchCalls,
  yt_units_est: ytUnits,
  tavily_credits: tavily,
  llm_input_tokens: tokensIn,
  llm_output_tokens: tokensOut,
  llm_cost_est_usd: +llmUsd.toFixed(4),
  notes: notesOut.join(' | ').slice(0, 1000),
  // heartbeat
  heartbeat_status: status === 'DEGRADED' ? 'down' : 'up',
  heartbeat_msg: (status === 'DEGRADED' ? `DEGRADED ${run.run_id}: ${deps.ai_error || 'AI unavailable'} | ` : `${status} ${run.run_id}: `)
    + `+${registered} leads, ${measured}/${screened.length} measured, ${p3r.length} researched, ${queued} queued, `
    + `${ytUnits}u/${tavily}cr/$${llmUsd.toFixed(3)} (${minutes} min)`,
  duration_ms: Math.round(minutes * 60000),
} }];

// R.3 Select Decisions
// A Review Queue row needs processing when the reviewer's decision is a real decision
// (APPROVE / REJECT / NEEDS_INFO, any spelling) and differs from what was already applied.
// PENDING and blank rows are ignored.
const normalise = v => ({
  APPROVE: 'APPROVE', APPROVED: 'APPROVE', YES: 'APPROVE',
  REJECT: 'REJECT', REJECTED: 'REJECT', NO: 'REJECT',
  NEEDS_INFO: 'NEEDS_INFO', NEED_INFO: 'NEEDS_INFO', NEEDSINFO: 'NEEDS_INFO', MORE_INFO: 'NEEDS_INFO',
})[String(v ?? '').trim().toUpperCase().replace(/[\s-]+/g, '_')] || '';

// Fingerprint of what the reviewer entered: a row already judged invalid is skipped until it changes,
// so an unfixed row does not get re-validated, re-written and re-logged every 30 minutes.
const fingerprint = r => {
  const s = [r.decision, r.reviewer, r.decision_reason_code, r.decision_reason].map(v => String(v ?? '').trim()).join('|');
  let h = 5381;
  for (let i = 0; i < s.length; i++) h = ((h * 33) ^ s.charCodeAt(i)) >>> 0;
  return h.toString(36);
};

const rows = $input.all().map(i => i.json).filter(r => r.channel_id);
const todo = rows
  .map(r => ({ row: r, decision: normalise(r.decision), fp: fingerprint(r) }))
  .filter(x => x.decision && x.decision !== normalise(x.row.applied_decision))
  .filter(x => !String(x.row.validation_message || '').includes(`[${x.fp}]`));

if (!todo.length) return [{ json: { work: false } }];
return todo.map(x => ({ json: { work: true, channel_id: x.row.channel_id, decision: x.decision, fp: x.fp, row: x.row } }));

// R.6 Plan Review Actions
// Validates each human decision and turns it into the writes it implies. A decision is applied only if
// the reviewer is named, a reason is given for REJECT / NEEDS_INFO, and the lead is still IN_REVIEW
// (an already-approved or closed lead is locked). Invalid rows get a validation_message instead.
const STAGE = { APPROVE: 'APPROVED', REJECT: 'REJECTED_HUMAN', NEEDS_INFO: 'NEEDS_INFO_HUMAN' };
const leads = new Map($input.all().map(i => [i.json.channel_id, i.json]));   // input = R.5 Read Leads
const now = DateTime.now().toUTC().toISO();

const decisions = $('R.3 Select Decisions').all().map(i => i.json).filter(x => x.work === true);

return decisions.map(x => {
  const r = x.row;
  const reviewer = String(r.reviewer || '').trim();
  const reason = String(r.decision_reason || '').trim();
  const reasonCode = String(r.decision_reason_code || '').trim().toUpperCase();
  const lead = leads.get(x.channel_id);
  const errors = [];
  if (!reviewer) errors.push('reviewer is required');
  if (x.decision !== 'APPROVE' && !reason && !reasonCode) errors.push('decision_reason_code or decision_reason is required');
  if (!lead) errors.push('lead not found in Leads');
  else if (lead.pipeline_stage !== 'IN_REVIEW') errors.push(`lead is ${lead.pipeline_stage}, expected IN_REVIEW`);
  const valid = errors.length === 0;
  const decidedAt = String(r.decision_date || '').trim() || now;

  return { json: {
    valid,
    decision: x.decision,
    channel_id: x.channel_id,
    queue_update: {
      channel_id: x.channel_id,
      applied_decision: valid ? x.decision : '',
      applied_at: valid ? now : '',
      decision_date: decidedAt,
      validation_message: valid ? `Applied ${x.decision} at ${now}` : `Not applied [${x.fp}]: ${errors.join('; ')}`,
    },
    lead_update: valid ? {
      channel_id: x.channel_id,
      pipeline_stage: STAGE[x.decision],
      review_decision: x.decision,
      reviewer,
      reviewed_at: decidedAt,
      reason_code: x.decision === 'APPROVE' ? 'APPROVED_BY_REVIEWER' : reasonCode || `HUMAN_${x.decision}`,
      reason_text: reason || `Reviewer decision: ${x.decision}`,
      last_updated_at: now,
    } : null,
    outreach: valid && x.decision === 'APPROVE' ? {
      channel_id: x.channel_id, channel_name: r.channel_name, channel_url: r.channel_url, tier: r.tier,
      score_total: r.score_total, host_name: r.host_name, host_role: r.host_role, business_name: r.business_name,
      business_website: r.business_website, contact_route_url: r.contact_route_url,
      personalization_note: r.personalization_note, approved_by: reviewer, approved_at: decidedAt,
    } : null,
    reject_log: valid && x.decision === 'REJECT' ? {
      log_id: `HUMAN-${x.channel_id}-${now.slice(0, 10)}`, channel_id: x.channel_id, channel_name: r.channel_name,
      channel_url: r.channel_url, rule: 'Human Review', reason_code: reasonCode || 'HUMAN_REJECT', reason_text: reason,
      evidence_text: r.component_scores || '', confidence: 'HIGH', rejected_by: reviewer, logged_at: now, run_id: 'REVIEW',
    } : null,
    review_minutes: Number(r.review_minutes) || 0,
  } };
});

// R.13 Summarise Review
// One Run Log row per review batch that actually had decisions to process.
const actions = $('R.6 Plan Review Actions').all().map(i => i.json);
const valid = actions.filter(a => a.valid);
const pt = DateTime.now().setZone('America/Los_Angeles');
const n = d => valid.filter(a => a.decision === d).length;
const invalid = actions.length - valid.length;
return [{ json: {
  run_id: `RV-${pt.toFormat('yyyyMMdd-HHmmss')}`,
  run_date_pt: pt.toISODate(),
  workflow: 'LE-REVIEW',
  trigger_type: 'SCHEDULE',
  started_at: DateTime.now().toUTC().toISO(),
  ended_at: DateTime.now().toUTC().toISO(),
  status: invalid ? 'PARTIAL' : 'SUCCESS',
  approved: n('APPROVE'),
  rejected_human: n('REJECT'),
  needs_info_human: n('NEEDS_INFO'),
  item_errors: invalid,
  notes: invalid ? `${invalid} decision(s) not applied - see validation_message in Review Queue` : '',
} }];
